<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=Inter:wght@400;500;600;700&display=swap');

  .rm-hero-home {
    --rm-primary: #0f0f1e;
    --rm-blue: #3a7bd5;
    --rm-orange: #e8531a;
    --rm-light: #f8f8fb;
    --rm-text-muted: #9aa3bd;
    --rm-radius: 8px;
    --rm-radius-lg: 20px;
    --rm-transition: 0.3s ease;
    --rm-font-display: "Playfair Display", Georgia, "Times New Roman", serif;
    --rm-font-body: "Inter", -apple-system, BlinkMacSystemFont, sans-serif;

    position: relative;
    overflow: hidden;
    background: var(--rm-primary);
    color: var(--rm-light);
    font-family: var(--rm-font-body);
    padding: 140px 20px 100px;
    box-sizing: border-box;
  }

  .rm-hero-home *,
  .rm-hero-home *::before,
  .rm-hero-home *::after {
    box-sizing: inherit;
  }

  /* ---------- Fondo: línea de firma + partículas + glows ---------- */
  .rm-hero-home__bg {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    pointer-events: none;
  }

  .rm-hero-home__topline {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--rm-blue), var(--rm-orange), var(--rm-blue));
    background-size: 200% 100%;
    animation: rm-hero-home-shimmer 6s linear infinite;
  }

  @keyframes rm-hero-home-shimmer {
    0% { background-position: 0% 0; }
    100% { background-position: 200% 0; }
  }

  .rm-hero-home__particles {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    display: block;
  }

  .rm-hero-home__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(110px);
    opacity: 0.28;
    animation: rm-hero-home-float 16s ease-in-out infinite;
  }

  .rm-hero-home__glow--blue {
    width: 520px;
    height: 520px;
    top: -160px;
    left: -120px;
    background: var(--rm-blue);
  }

  .rm-hero-home__glow--orange {
    width: 460px;
    height: 460px;
    bottom: -180px;
    right: -120px;
    background: var(--rm-orange);
    animation-delay: -8s;
  }

  @keyframes rm-hero-home-float {
    0%, 100% { transform: translate(0, 0) scale(1); }
    50% { transform: translate(30px, 24px) scale(1.08); }
  }

  /* ---------- Contenedor ---------- */
  .rm-hero-home__container {
    position: relative;
    z-index: 1;
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1.05fr 0.95fr;
    align-items: center;
    gap: 60px;
  }

  .rm-hero-home__content > *,
  .rm-hero-home__visual {
    opacity: 0;
    transform: translateY(16px);
    animation: rm-hero-home-fadein 0.6s ease forwards;
  }

  @keyframes rm-hero-home-fadein {
    to { opacity: 1; transform: translateY(0); }
  }

  /* ---------- Badge ---------- */
  .rm-hero-home__badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 7px 16px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.12);
    font-family: var(--rm-font-body);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #cbd5e1;
    margin-bottom: 28px;
  }

  .rm-hero-home__badge-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    animation: rm-hero-home-blink 2.2s ease-in-out infinite;
  }

  @keyframes rm-hero-home-blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.25; }
  }

  /* ---------- Titular ---------- */
  .rm-hero-home__title {
    font-family: var(--rm-font-display);
    font-weight: 700;
    font-size: clamp(2.1rem, 1.3rem + 3vw, 3.4rem);
    line-height: 1.18;
    color: var(--rm-light);
    max-width: 15ch;
    margin: 0 0 22px;
  }

  .rm-hero-home__subtitle {
    font-size: 17px;
    line-height: 1.65;
    color: var(--rm-text-muted);
    max-width: 46ch;
    margin: 0 0 40px;
  }

  /* ---------- CTAs ---------- */
  .rm-hero-home__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 18px;
  }

  .rm-hero-home__cta {
    position: relative;
    display: inline-flex;
    align-items: center;
    font-family: var(--rm-font-body);
    font-size: 15px;
    font-weight: 600;
    text-decoration: none;
    border-radius: var(--rm-radius);
    padding: 15px 26px;
    transition: transform var(--rm-transition), box-shadow var(--rm-transition), border-color var(--rm-transition), color var(--rm-transition);
    overflow: hidden;
  }

  .rm-hero-home__cta--primary {
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    color: #ffffff;
    box-shadow: 0 12px 28px rgba(58, 123, 213, 0.28);
  }

  .rm-hero-home__cta--primary::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(160px circle at var(--rm-mx, 50%) var(--rm-my, 50%), rgba(255, 255, 255, 0.32), transparent 70%);
    opacity: 0;
    transition: opacity var(--rm-transition);
  }

  .rm-hero-home__cta--primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 16px 34px rgba(232, 83, 26, 0.35);
  }

  .rm-hero-home__cta--primary:hover::before {
    opacity: 1;
  }

  .rm-hero-home__cta--primary span {
    position: relative;
    z-index: 1;
  }

  .rm-hero-home__cta--secondary {
    color: #e5e7eb;
    border: 1.5px solid rgba(255, 255, 255, 0.28);
    background: transparent;
  }

  .rm-hero-home__cta--secondary:hover {
    border-color: var(--rm-blue);
    color: #ffffff;
  }

  /* ---------- Panel hub ---------- */
  .rm-hero-home__visual {
    position: relative;
    width: 100%;
  }

  .rm-hero-home__panel {
    position: relative;
    width: 100%;
    max-width: 420px;
    aspect-ratio: 1 / 1;
    margin: 0 auto;
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
  }

  .rm-hero-home__hub-lines {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
  }

  .rm-hero-home__hub-line {
    stroke: rgba(148, 163, 184, 0.28);
    stroke-width: 0.4;
    transition: stroke 0.5s ease, stroke-width 0.5s ease;
  }

  .rm-hero-home__hub-line.is-active {
    stroke: url(#rmHomeHubActive);
    stroke-width: 0.7;
  }

  .rm-hero-home__hub-core {
    fill: #12121f;
    stroke: rgba(255, 255, 255, 0.18);
    stroke-width: 0.4;
  }

  .rm-hero-home__hub-center {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    font-family: var(--rm-font-body);
    font-size: 11px;
    font-weight: 600;
    color: #f4f4fa;
    white-space: nowrap;
    pointer-events: none;
  }

  .rm-hero-home__hub-center span {
    color: #7dd3fc;
  }

  .rm-hero-home__hub-node {
    position: absolute;
    transform: translate(-50%, -50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    width: 78px;
    padding: 10px 4px;
    background: transparent;
    border: none;
    cursor: pointer;
    font-family: var(--rm-font-body);
  }

  .rm-hero-home__hub-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(15, 15, 30, 0.6);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: #a9b4d0;
    transition: color 0.4s ease, border-color 0.4s ease, box-shadow 0.4s ease, transform 0.4s ease;
  }

  .rm-hero-home__hub-icon svg {
    width: 18px;
    height: 18px;
  }

  .rm-hero-home__hub-label {
    font-size: 11px;
    font-weight: 500;
    color: #7d84a0;
    text-align: center;
    line-height: 1.2;
    transition: color 0.4s ease;
  }

  .rm-hero-home__hub-node.is-active .rm-hero-home__hub-icon {
    color: #fff;
    border-color: transparent;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    box-shadow: 0 0 0 4px rgba(58, 123, 213, 0.18), 0 8px 24px rgba(232, 83, 26, 0.3);
    transform: scale(1.08);
  }

  .rm-hero-home__hub-node.is-active .rm-hero-home__hub-label {
    color: #f4f4fa;
  }

  .rm-hero-home__hub-caption {
    position: absolute;
    left: 50%;
    bottom: -46px;
    transform: translateX(-50%);
    width: max-content;
    max-width: 90%;
    display: flex;
    align-items: baseline;
    gap: 8px;
    text-align: center;
    font-family: var(--rm-font-body);
  }

  .rm-hero-home__hub-caption-title {
    font-size: 13px;
    font-weight: 600;
    color: #f4f4fa;
  }

  .rm-hero-home__hub-caption-text {
    font-size: 12px;
    color: #7d84a0;
  }

  @media (prefers-reduced-motion: reduce) {
    .rm-hero-home__topline,
    .rm-hero-home__glow,
    .rm-hero-home__badge-dot {
      animation: none;
    }
    .rm-hero-home__content > *,
    .rm-hero-home__visual {
      opacity: 1;
      transform: none;
      animation: none;
    }
  }

  /* ---------- Responsive ---------- */
  @media (max-width: 980px) {
    .rm-hero-home {
      padding: 90px 20px 60px;
    }

    .rm-hero-home__container {
      grid-template-columns: 1fr;
      gap: 56px;
    }

    .rm-hero-home__visual {
      order: -1;
      max-width: 440px;
      margin: 0 auto;
    }

    .rm-hero-home__title {
      max-width: 100%;
    }

    .rm-hero-home__subtitle {
      max-width: 60ch;
    }

    .rm-hero-home__panel {
      max-width: 340px;
    }

    .rm-hero-home__hub-node {
      width: 64px;
    }

    .rm-hero-home__hub-icon {
      width: 34px;
      height: 34px;
    }

    .rm-hero-home__hub-icon svg {
      width: 15px;
      height: 15px;
    }

    .rm-hero-home__hub-label {
      font-size: 10px;
    }
  }

  @media (max-width: 767px) {
    .rm-hero-home {
      padding: 64px 16px 40px;
    }

    .rm-hero-home__actions {
      flex-direction: column;
      align-items: stretch;
    }

    .rm-hero-home__cta {
      justify-content: center;
      text-align: center;
    }
  }
</style>

<script>
  (function () {
    var section = document.currentScript.closest('.rm-hero-home');
    if (!section) return;

    /* Particle canvas */
    var canvas = section.querySelector('.rm-hero-home__particles');
    if (canvas && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      var ctx = canvas.getContext('2d');
      var particles = [];
      var count = 46;
      var w, h;

      function resize() {
        w = canvas.width = canvas.offsetWidth;
        h = canvas.height = canvas.offsetHeight;
      }

      function init() {
        particles = [];
        for (var i = 0; i < count; i++) {
          particles.push({
            x: Math.random() * w,
            y: Math.random() * h,
            vx: (Math.random() - 0.5) * 0.25,
            vy: (Math.random() - 0.5) * 0.25
          });
        }
      }

      function step() {
        ctx.clearRect(0, 0, w, h);
        for (var i = 0; i < particles.length; i++) {
          var p = particles[i];
          p.x += p.vx;
          p.y += p.vy;
          if (p.x < 0 || p.x > w) p.vx *= -1;
          if (p.y < 0 || p.y > h) p.vy *= -1;
        }
        for (var i = 0; i < particles.length; i++) {
          for (var j = i + 1; j < particles.length; j++) {
            var a = particles[i], b = particles[j];
            var dx = a.x - b.x, dy = a.y - b.y;
            var dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < 140) {
              ctx.strokeStyle = 'rgba(58,123,213,' + (0.16 * (1 - dist / 140)) + ')';
              ctx.lineWidth = 1;
              ctx.beginPath();
              ctx.moveTo(a.x, a.y);
              ctx.lineTo(b.x, b.y);
              ctx.stroke();
            }
          }
        }
        for (var i = 0; i < particles.length; i++) {
          ctx.fillStyle = 'rgba(125,211,252,0.55)';
          ctx.beginPath();
          ctx.arc(particles[i].x, particles[i].y, 1.4, 0, Math.PI * 2);
          ctx.fill();
        }
        requestAnimationFrame(step);
      }

      resize();
      init();
      step();
      window.addEventListener('resize', function () {
        resize();
        init();
      });
    }

    /* Hub panel rotation */
    var panel = section.querySelector('.rm-hero-home__panel');
    if (panel) {
      var nodes = panel.querySelectorAll('.rm-hero-home__hub-node');
      var lines = panel.querySelectorAll('.rm-hero-home__hub-line');
      var captionTitle = panel.querySelector('.rm-hero-home__hub-caption-title');
      var captionText = panel.querySelector('.rm-hero-home__hub-caption-text');
      var data = [
        ['Dominio', 'Tu .es o .com, gestionado por nosotros.'],
        ['Web', 'Diseño profesional, listo para vender.'],
        ['Tienda online', 'Catálogo y cobros, sin plugins sueltos.'],
